code:
aspath_make_str_count (struct aspath *as)
{
struct assegment *seg;
int str_size;
int len = 0;
char *str_buf;
if (!as->segments)
{
as->str = XMALLOC (MTYPE_AS_STR, 1);
as->str[0] = '\0';
as->str_len = 0;
return;
}
seg = as->segments;
#define ASN_STR_LEN (10 + 1)
str_size = MAX (assegment_count_asns (seg, 0) * ASN_STR_LEN + 2 + 1,
ASPATH_STR_DEFAULT_LEN);
str_buf = XMALLOC (MTYPE_AS_STR, str_size);
while (seg)
{
int i;
char seperator;
switch (seg->type)
{
case AS_SET:
case AS_CONFED_SET:
seperator = ',';
break;
case AS_SEQUENCE:
case AS_CONFED_SEQUENCE:
seperator = ' ';
break;
default:
XFREE (MTYPE_AS_STR, str_buf);
as->str = NULL;
as->str_len = 0;
return;
}
#define SEGMENT_STR_LEN(X) (((X)->length * ASN_STR_LEN) + 2 + 1 + 1)
if ( (len + SEGMENT_STR_LEN(seg)) > str_size)
{
str_size = len + SEGMENT_STR_LEN(seg);
str_buf = XREALLOC (MTYPE_AS_STR, str_buf, str_size);
}
#undef ASN_STR_LEN
#undef SEGMENT_STR_LEN
if (seg->type != AS_SEQUENCE)
len += snprintf (str_buf + len, str_size - len,
"%c",
aspath_delimiter_char (seg->type, AS_SEG_START));
for (i = 0; i < seg->length; i++)
{
len += snprintf (str_buf + len, str_size - len, "%u", seg->as[i]);
if (i < (seg->length - 1))
len += snprintf (str_buf + len, str_size - len, "%c", seperator);
}
if (seg->type != AS_SEQUENCE)
len += snprintf (str_buf + len, str_size - len, "%c",
aspath_delimiter_char (seg->type, AS_SEG_END));
if (seg->next)
len += snprintf (str_buf + len, str_size - len, " ");
seg = seg->next;
}
assert (len < str_size);
str_buf[len] = '\0';
as->str = str_buf;
as->str_len = len;
return;
}

