{
struct vfs_fsp_data *curr;
struct vfs_fsp_data *prev;
for (curr = fsp->vfs_extension, prev = NULL;
curr;
prev = curr, curr = curr->next) {
if (curr->owner == handle) {
if (prev) {
prev->next = curr->next;
} else {
fsp->vfs_extension = curr->next;
}
if (curr->destroy) {
curr->destroy(EXT_DATA_AREA(curr));
}
TALLOC_FREE(curr);
return;
}
}
}

