http_buf_size += len_read;
}
ch = php_stream_getc(stream);
if (ch == '\r') {
ch = php_stream_getc(stream);
}
if (ch != '\n') {
if (http_buf) {
zend_string_release(http_buf);
}
return NULL;
}
}
} else {
if (http_buf) {
zend_string_release(http_buf);
}
return NULL;
}
if (buf_size == 0) {
done = TRUE;
}
}
while (1) {
if (!php_stream_gets(stream, headerbuf, sizeof(headerbuf))) {
break;
}
if ((headerbuf[0] == '\r' && headerbuf[1] == '\n') ||
