static int bdrv_assign_node_name(BlockDriverState *bs,
const char *node_name,
Error **errp)
{
if (!node_name) {
return 0;
}
if (node_name[0] == '\0') {
error_setg(errp, "Empty node name");
return -EINVAL;
}
if (bdrv_find(node_name)) {
