if (cert == NULL) {
continue;
}
if (!X509_STORE_add_cert (ctx->cert_store, cert)) {
X509_free (cert);
continue;
}
count++;
X509_free (cert);
}
CertCloseStore (hStore, 0);
hStore = CertOpenSystemStore (0, L"ROOT");
