} else if (strcmp(cg->subsystem, "memory.limit_in_bytes") == 0 && memsw_limit != NULL) {
item->elem = memsw_limit->elem;
memsw_limit->elem = it->elem;
}
lxc_list_add_tail(result, item);
}
return result;
}

