continue;
if (lblk >= mpd->map.m_lblk + mpd->map.m_len) {
mpd->map.m_len = 0;
mpd->map.m_flags = 0;
err = mpage_process_page_bufs(mpd, head,
bh, lblk);
pagevec_release(&pvec);
if (err > 0)
err = 0;
return err;
}
if (buffer_delay(bh)) {
clear_buffer_delay(bh);
bh->b_blocknr = pblock++;
