clear_buffer_unwritten(bh);
} while (lblk++, (bh = bh->b_this_page) != head);
mpd->io_submit.io_end->size += PAGE_CACHE_SIZE;
err = mpage_submit_page(mpd, page);
if (err < 0) {
pagevec_release(&pvec);
return err;
