img->maxcolorcode[IW_CHANNELTYPE_GRAY],
img->maxcolorcode[IW_CHANNELTYPE_ALPHA]))
{
goto done;
}
}
else {
if(!setup_16_32bit(wctx,255,255,255,255)) {
goto done;
}
}
}
