static void cxusb_d680_dmb_drain_message(struct dvb_usb_device *d)
{
int       ep = d->props.generic_bulk_ctrl_endpoint;
const int timeout = 100;
const int junk_len = 32;
u8        *junk;
int       rd_count;
junk = kmalloc(junk_len, GFP_KERNEL);
