void bandwidth_set(pid_t pid, const char *dev, int down, int up) {
bandwidth_create_run_file(pid);
char *txt;
if (asprintf(&txt, "%s: RX %dKB/s, TX %dKB/s", dev, down, up) == -1)
errExit("asprintf");
read_bandwidth_file(pid);
IFBW *ptr = ifbw_find(dev);
if (ptr) {
