free(ptr->txt);
ptr->txt = txt;
}
else {
IFBW *ifbw_new = malloc(sizeof(IFBW));
if (!ifbw_new)
errExit("malloc");
memset(ifbw_new, 0, sizeof(IFBW));
ifbw_new->txt = txt;
ifbw_add(ifbw_new);
}
write_bandwidth_file(pid) ;
}

