opt->nd_opt_mtu_type = ND_OPT_MTU;
opt->nd_opt_mtu_len = 1;
opt->nd_opt_mtu_reserved = 0;
opt->nd_opt_mtu_mtu = htonl (zif->rtadv.AdvLinkMTU);
len += sizeof (struct nd_opt_mtu);
