ERROR("%s: -data-queue missing or invalid "
"queue size\n", argv[0]);
exit(1);
}
if(data_buffer_size < 1) {
ERROR("%s: -data-queue should be 1 Mbyte or "
"larger\n", argv[0]);
exit(1);
}
