report_config_error(CONFIG_GENERAL_ERROR, "(%s) cannot use a loopback interface (%s) for vrrp - ignoring", vrrp->iname, vrrp->ifp->ifname);
vrrp->ifp = NULL;
}
#ifdef _HAVE_VRRP_VMAC_
vrrp->configured_ifp = vrrp->ifp;
#endif
}

