pgp_update_card_algorithms(sc_card_t *card, sc_cardctl_openpgp_keygen_info_t *key_info)
{
sc_algorithm_info_t *algo;
u8 id = key_info->keytype;
LOG_FUNC_CALLED(card->ctx);
if (id > card->algorithm_count) {
sc_log(card->ctx,
