ptaWriteMem(l_uint8  **pdata,
size_t    *psize,
PTA       *pta,
l_int32    type)
{
l_int32  ret;
FILE    *fp;
PROCNAME("ptaWriteMem");
if (pdata) *pdata = NULL;
if (psize) *psize = 0;
if (!pdata)
return ERROR_INT("&data not defined", procName, 1);
if (!psize)
return ERROR_INT("&size not defined", procName, 1);
