return DECLINED;
}
if (claims)
oidc_util_json_merge(r, id_token, claims);
int rc = oidc_authz_worker22(r, claims ? claims : id_token, reqs,
reqs_arr->nelts);
if (claims)
json_decref(claims);
if (id_token)
json_decref(id_token);
if ((rc == HTTP_UNAUTHORIZED) && ap_auth_type(r))
rc = oidc_handle_unauthorized_user22(r);
return rc;
}

