}
if (cmd->argc-1 >= 2 &&
strcasecmp(cmd->argv[2], "dirmode") != 0 &&
strcasecmp(cmd->argv[2], "skel") != 0) {
char *tmp = NULL;
mode = strtol(cmd->argv[2], &tmp, 8);
if (tmp && *tmp)
CONF_ERROR(cmd, pstrcat(cmd->tmp_pool, ": bad mode parameter: '",
cmd->argv[2], "'", NULL));
start = 3;
}
if (cmd->argc-1 > 2) {
