CONF_ERROR(cmd, pstrcat(cmd->tmp_pool, "unable to stat '",
skel_path, "': ", strerror(errno), NULL));
}
if (!S_ISDIR(st.st_mode)) {
CONF_ERROR(cmd, pstrcat(cmd->tmp_pool, "'", skel_path,
"' is not a directory", NULL));
}
