errExit("asprintf");
return new_name;
}
else if (strncmp(path, "~/", 2) == 0) {
if (asprintf(&new_name, "%s%s", homedir, path + 1) == -1)
errExit("asprintf");
return new_name;
}
return strdup(path);
}

