}
if (mainFrame->eventHandler()->sendContextMenuEvent(event))
return false;
WebCore::ContextMenu* coreMenu =
priv->page->contextMenuController()->contextMenu();
if (!coreMenu) {
return mouse_press_handled;
}
return true;
#else
