static int GetElementId(BitReader* reader) {
if (reader->bits_available() >= 8) {
int num_bits_to_read = 0;
static int prefix[] = { 0x80, 0x4000, 0x200000, 0x10000000 };
for (int i = 0; i < 4; ++i) {
