offset += 12;
} else {
reader.SkipBits(22);
RCHECK(ReadBits(&reader, 2) == 3);
reader.SkipBits(5);
int pack_stuffing_length = ReadBits(&reader, 3);
offset += 14 + pack_stuffing_length;
