break;
case IVD_CMD_REL_DISPLAY_FRAME:
u4_api_ret = ih264d_rel_display_frame(dec_hdl, (void *)pv_api_ip,
(void *)pv_api_op);
break;
case IV_CMD_RETRIEVE_MEMREC:
