size = max_tile_cols * max_tile_rows;
size  += max_ctb_rows;
size *= sizeof(WORD32);
pv_buf = ps_codec->pf_aligned_alloc(pv_mem_ctxt, 128, size);
RETURN_IF((NULL == pv_buf), IV_FAIL);
