ps_pu->b2_part_idx = 0;
ps_pu = ps_codec->s_parse.ps_pu;
ihevcd_parse_prediction_unit(ps_codec, x0 + (cb_size * 3 / 4), y0, cb_size / 4, cb_size);
ps_pu->b2_part_idx = 1;
}
else
{
pu_t *ps_pu = ps_codec->s_parse.ps_pu;
