chunk[5]=0;
chunk[6]=1;
chunk[7]=0;
chunk[8]=1;
chunk[9]=0;
PNGLong(chunk+10,(png_uint_32) (0L));
chunk[14]=0;
PNGLong(chunk+15,(png_uint_32) (mng_info->page.x));
PNGLong(chunk+19,
(png_uint_32) (mng_info->page.x + ping_width));
PNGLong(chunk+23,(png_uint_32) (mng_info->page.y));
PNGLong(chunk+27,
(png_uint_32) (mng_info->page.y + ping_height));
