u4_offset++;
if (u4_curr_bit == 31)
{
ps_stream->u4_buf      = ps_stream->u4_buf_nxt;
if (ps_stream->u4_offset < ps_stream->u4_max_offset)
{
u4_temp             = *(ps_stream->pu4_buf_aligned)++;
CONV_LE_TO_BE(ps_stream->u4_buf_nxt,u4_temp)
}
}
ps_stream->u4_offset          = u4_offset;
